  headingIds: withHeadingIds = false,
  typeScale = "compact",
  annotations,
  activeAnnotationId = null,
  onAnnotationClick,
  annotationCounts = "never",
  annotationLabel = defaultAnnotationLabel,
  annotationCountLabel = defaultAnnotationCountLabel,
  onAnnotationsLayout,
  onCreateAnnotation,
  commentLabel = "Comment",
  floatingSafeArea,
  onOutlineChange,
  headingAnchors,
  headingLinkHref,
  sectionMarks,
  onSectionMark,
  toggleState,
  findQuery,
  onFindClose,
  findLabels,
  tableLabel,
  mentionHref,
  mentionImage,
  mentionStatus,
  fileLinkPrefix = "/api/files/",
  embeds,
  fileContentType,
  citation,
  blockViews,
  renderTaskQuery,
  className,
  ...props
